// Disposable, synthetic capture-account setup and verified cleanup.
// Example: CAPTURE_CHECK_OUT=/tmp/capture-check node --env-file=.env.test.local tests/fixtures/capture-acceptance.mjs setup
import fs from'node:fs/promises';import path from'node:path';import{randomUUID}from'node:crypto';import{execFileSync}from'node:child_process';import{fileURLToPath}from'node:url';
const out=path.resolve(process.env.CAPTURE_CHECK_OUT??''),repo=path.resolve(fileURLToPath(new URL('../../',import.meta.url))),app=process.env.APP_URL,url=process.env.NEXT_PUBLIC_SUPABASE_URL,db=process.env.TEST_SQL_DATABASE_URL??process.env.SUPABASE_DB_URL,storage=process.env.TEST_STORAGE_DIR;
if(process.env.MFA_TEST_DISPOSABLE!=='1'||!process.env.CAPTURE_CHECK_OUT||[app,url,db].some(x=>!x||!['127.0.0.1','localhost','[::1]'].includes(new URL(x).hostname))||out===repo||out.startsWith(repo+path.sep))throw Error('Disposable loopback configuration and an output directory outside the checkout are required');
const {createClient}=await import('@supabase/supabase-js'),{createServerClient}=await import('@supabase/ssr');
const admin=createClient(url,process.env.SUPABASE_SECRET_KEY,{auth:{persistSession:false,autoRefreshToken:false}}),sql=query=>execFileSync('psql',['-XqAt','--dbname',db,'-v','ON_ERROR_STOP=1'],{input:query,encoding:'utf8'}).trim(),ledger=out+'/fixture-ledger.json';
await fs.mkdir(out,{recursive:true,mode:0o700});await fs.chmod(out,0o700);
const mode=process.argv[2];const uuid=value=>typeof value==='string'&&/^[a-f0-9-]{36}$/.test(value);
if(mode==='setup'){
 try{await fs.access(ledger);throw Error('Fixture ledger already exists; clean it up before creating another account');}catch(e){if(e.code!=='ENOENT')throw e;}
 const tag=randomUUID().slice(0,8),f={email:'text1287-'+tag+'@example.com',handle:'text1287_'+tag,password:'Local-'+randomUUID()+'!'},write=()=>fs.writeFile(ledger,JSON.stringify(f),{mode:0o600});
 await write();const user=await admin.auth.admin.createUser({email:f.email,password:f.password,email_confirm:true});if(user.error)throw user.error;f.user=user.data.user.id;await write();
 const profile=await admin.from('profiles').insert({id:f.user,handle:f.handle,hints_seen:['capture','modes','thumbs','thread']});if(profile.error)throw profile.error;
 f.post=sql("select public.create_food_post('"+f.user+"',now(),'Local rice fixture',150,'{\"calories\":180,\"protein_g\":4,\"carbs_g\":42,\"fat_g\":0,\"micronutrients\":[]}'::jsonb);");if(!uuid(f.post))throw Error('Fixture post was not created');await write();
 sql("update posts set status='ready' where id='"+f.post+"' and user_id='"+f.user+"';");
 f.modelComment=sql("insert into post_comments(post_id,author,body) values('"+f.post+"','model','Consumed: Local rice, 150 g. This is scripted test content.') returning id;");if(!uuid(f.modelComment))throw Error('Fixture comment was not created');await write();
 const cookies=[],client=createServerClient(url,process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,{cookies:{getAll:()=>cookies,setAll:rows=>{for(const row of rows){const i=cookies.findIndex(c=>c.name===row.name);if(i<0)cookies.push(row);else cookies[i]=row;}}}});
 const signed=await client.auth.signInWithPassword({email:f.email,password:f.password});if(signed.error)throw signed.error;
 await fs.writeFile(out+'/session.json',JSON.stringify(cookies),{mode:0o600});
 const {writeEan13}=await import('./barcode-image.mjs');await writeEan13('0016000275683',out+'/known-ean.png');
 console.log(JSON.stringify({fixtureCreated:true}));
}else if(mode==='cleanup'){
 const f=JSON.parse(await fs.readFile(ledger,'utf8'));if(!uuid(f.user)||!/^text1287-[a-f0-9]+@example.com$/.test(f.email)||!storage||!path.isAbsolute(storage))throw Error('Owned disposable fixture required');
 // The storage directory is generated by test-stack.mjs, not named by a magic substring.
 const stackRoot=path.dirname(storage),stack=JSON.parse(await fs.readFile(path.join(stackRoot,'state.json'),'utf8'));
 if(path.basename(storage)!=='objects'||stack.pg!==path.join(stackRoot,'pg')||stack.stopped||!/^mfa-test-auth-/.test(stack.names?.auth??''))throw Error('Live disposable test-stack storage required');
 const user=await admin.auth.admin.getUserById(f.user);if(user.error||user.data.user?.email!==f.email)throw Error('Fixture ownership check failed');
 let jar=JSON.parse(await fs.readFile(out+'/session.json','utf8'));const client=createServerClient(url,process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,{cookies:{getAll:()=>jar,setAll:rows=>{for(const row of rows){const i=jar.findIndex(c=>c.name===row.name);if(i<0)jar.push(row);else jar[i]=row;}}}});
 const signedOut=await client.auth.signOut({scope:'local'});if(signedOut.error)throw signedOut.error;
 const ids=JSON.parse(sql("select coalesce(json_agg(id),'[]') from(select id from posts where user_id='"+f.user+"' union select id from post_upload_drafts where user_id='"+f.user+"')q"));if(!ids.every(uuid))throw Error('Invalid owned post ID');
 const list=ids.length?ids.map(x=>"'"+x+"'").join(','):'null',jobs=JSON.parse(sql("select coalesce(json_agg(id),'[]') from jobs where post_id in("+list+") or id in(select cleanup_job_id from post_upload_drafts where user_id='"+f.user+"')"));if(!jobs.every(uuid))throw Error('Invalid owned job ID');const joblist=jobs.length?jobs.map(x=>"'"+x+"'").join(','):'null';
 await fs.writeFile(out+'/cleanup-before.json',JSON.stringify({user:f.user,ids,jobs},null,2),{mode:0o600});
 sql("begin;delete from saved_meals where user_id='"+f.user+"';delete from jobs where id in("+joblist+");delete from upload_failures where post_id in("+list+");delete from storage.objects where bucket_id='media' and name like '"+f.user+"/%';delete from auth.users where id='"+f.user+"' and email='"+f.email+"';commit;");
 await fs.rm(path.join(storage,'media',f.user),{recursive:true,force:true});
 const absent=JSON.parse(sql("select json_build_object('auth',(select count(*) from auth.users where id='"+f.user+"'),'profiles',(select count(*) from profiles where id='"+f.user+"'),'posts',(select count(*) from posts where user_id='"+f.user+"'),'drafts',(select count(*) from post_upload_drafts where user_id='"+f.user+"'),'jobs',(select count(*) from jobs where id in("+joblist+") or post_id in("+list+")),'media',(select count(*) from post_media where post_id in("+list+")),'comments',(select count(*) from post_comments where post_id in("+list+")),'storage',(select count(*) from storage.objects where bucket_id='media' and name like '"+f.user+"/%'),'sessions',(select count(*) from auth.sessions where user_id='"+f.user+"'))"));
 if(Object.values(absent).some(Boolean))throw Error('Fixture cleanup readback is not zero');
 await fs.writeFile(out+'/cleanup.json',JSON.stringify({at:new Date().toISOString(),ownLocalSignout:true,absent},null,2));
 for(const name of['session.json','legacy-session.json','text/session.json','text/fixture-ledger.json'])await fs.rm(out+'/'+name,{force:true});
 delete f.password;await fs.writeFile(ledger,JSON.stringify(f,null,2));console.log(JSON.stringify({cleanupVerified:true,absent}));
}else throw Error('Use setup or cleanup');
